'use strict';
const H={dot:(a,b)=>a.reduce((v,x,i)=>v+x*b[i],0)};
const p={"pixel":0.5,"bias":0};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 先写清输入和权重的形状
Object.assign(s, ((s,p)=>({image:[p.pixel,1],weights:[[1,-1],[-1,1]],bias:[p.bias,0]}))(s, p));
// 矩阵乘法产生分数
Object.assign(s, ((s,p)=>({scores:s.weights.map((w,i)=>H.dot(w,s.image)+s.bias[i])}))(s, p));
// 选分数最大的类别
Object.assign(s, ((s,p)=>({classId:s.scores[0]>=s.scores[1]?0:1}))(s, p));
// 做一个独立输入扰动
Object.assign(s, ((s,p)=>({changedImage:[1-p.pixel,1],changedScores:s.weights.map((w,i)=>H.dot(w,[1-p.pixel,1])+s.bias[i])}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={softmax:xs=>{const m=Math.max(...xs),e=xs.map(x=>Math.exp(x-m)),z=e.reduce((a,b)=>a+b,0);return e.map(x=>x/z);}};
const p={"score":2,"temperature":1};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 固定标签并缩放logit
Object.assign(s, ((s,p)=>({logits:[p.score,1,0],label:0}))(s, p));
// 稳定计算softmax
Object.assign(s, ((s,p)=>({probabilities:H.softmax(s.logits.map(x=>x/p.temperature))}))(s, p));
// 交叉熵只读取真类概率
Object.assign(s, ((s,p)=>({loss:-Math.log(s.probabilities[s.label])}))(s, p));
// 回传到原始logit
Object.assign(s, ((s,p)=>({gradient:s.probabilities.map((x,i)=>(x-Number(i===s.label))/p.temperature)}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={};
const p={"weight":1,"x":2};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 展开一个带ReLU的计算图
Object.assign(s, ((s,p)=>({preactivation:p.weight*p.x-.5}))(s, p));
// 先完成前向损失
Object.assign(s, ((s,p)=>({activation:Math.max(0,s.preactivation),loss:(Math.max(0,s.preactivation)-1)**2/2}))(s, p));
// 按链式法则反向求导
Object.assign(s, ((s,p)=>({gradient:(s.activation-1)*(s.preactivation>0?1:0)*p.x}))(s, p));
// 用独立差分检查光滑点
Object.assign(s, ((s,p)=>{const f=w=>(Math.max(0,w*p.x-.5)-1)**2/2,h=1e-5;return {numerical:(f(p.weight+h)-f(p.weight-h))/(2*h),smooth:Math.abs(s.preactivation)>Math.abs(p.x*h)};})(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={sum:xs=>xs.reduce((a,b)=>a+b,0)};
const p={"center":1};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 固定图像、卷积核与边界
Object.assign(s, ((s,p)=>({image:[[1,2,3],[0,p.center,2],[1,0,1]],kernel:[[1,0],[0,-1]]}))(s, p));
// 滑动做互相关
Object.assign(s, ((s,p)=>({output:[0,1].map(i=>[0,1].map(j=>H.sum([0,1].flatMap(a=>[0,1].map(b=>s.image[i+a][j+b]*s.kernel[a][b])))))}))(s, p));
// 对每个输出应用ReLU
Object.assign(s, ((s,p)=>({activated:s.output.map(row=>row.map(x=>Math.max(0,x)))}))(s, p));
// 进行2×2最大池化
Object.assign(s, ((s,p)=>({pooled:Math.max(...s.activated.flat()),outputWidth:2,sharedParameters:4}))(s, p));
console.log(JSON.stringify(s,null,2));

'use strict';
const H={};
const p={"x":1,"scale":0.5};
const s={};
// p 是输入参数；s 保存此前步骤的结果；H 是本文件中的纯计算辅助函数。
// 区分直接映射与残差映射
Object.assign(s, ((s,p)=>({input:p.x,residual:p.scale*p.x}))(s, p));
// 合并快捷连接
Object.assign(s, ((s,p)=>({output:s.input+s.residual}))(s, p));
// 比较输入梯度路径
Object.assign(s, ((s,p)=>({plainGradient:p.scale,residualGradient:1+p.scale}))(s, p));
// 检查抵消反例
Object.assign(s, ((s,p)=>({gradientCanceled:Math.abs(s.residualGradient)<1e-9}))(s, p));
console.log(JSON.stringify(s,null,2));

